 // Escape hatch: if the overlay ever appears wrongly, the user must be able to get out of it
 function _dismissRebootOverlay() {
     if (_rebootOverlay) _rebootOverlay.remove();
     _rebootOverlay = null;
     _rebootFails = 0;
